create table public.families (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 120), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.family_accounts (family_id uuid not null references public.families(id) on delete cascade, account_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(family_id), unique(account_id));
create table public.people (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, last_name text not null check(char_length(last_name) between 1 and 100), first_name text not null check(char_length(first_name) between 1 and 100), middle_name text check(middle_name is null or char_length(middle_name)<=100), birth_date date not null check(birth_date<=current_date), sex text not null check(sex in ('male','female','unspecified')), family_role text check(family_role is null or char_length(family_role)<=50), status text not null default 'active' check(status in ('active','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,family_id));
create index people_family_created_idx on public.people(family_id,created_at,id);
create table public.medical_profiles (id uuid primary key default gen_random_uuid(), family_id uuid not null, person_id uuid not null, blood_group text check(blood_group in ('o','a','b','ab')), rhesus_factor text check(rhesus_factor in ('positive','negative')), general_comment text check(general_comment is null or char_length(general_comment)<=5000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(person_id,family_id), unique(id,family_id), foreign key(person_id,family_id) references public.people(id,family_id) on delete cascade);
create table public.medical_profile_items (id uuid primary key default gen_random_uuid(), family_id uuid not null, medical_profile_id uuid not null, category text not null check(category in ('allergy','chronic_condition','warning')), name text not null check(char_length(name) between 1 and 200), description text check(description is null or char_length(description)<=2000), status text not null check(status in ('active','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(medical_profile_id,family_id) references public.medical_profiles(id,family_id) on delete cascade);
alter table public.families enable row level security; alter table public.families force row level security; alter table public.family_accounts enable row level security; alter table public.family_accounts force row level security; alter table public.people enable row level security; alter table public.people force row level security; alter table public.medical_profiles enable row level security; alter table public.medical_profiles force row level security; alter table public.medical_profile_items enable row level security; alter table public.medical_profile_items force row level security;
create policy family_accounts_read on public.family_accounts for select using (account_id=auth.uid());
create policy families_member on public.families for all using (exists(select 1 from public.family_accounts fa where fa.family_id=id and fa.account_id=auth.uid())) with check (exists(select 1 from public.family_accounts fa where fa.family_id=id and fa.account_id=auth.uid()));
create policy people_member on public.people for all using (exists(select 1 from public.family_accounts fa where fa.family_id=people.family_id and fa.account_id=auth.uid())) with check (exists(select 1 from public.family_accounts fa where fa.family_id=people.family_id and fa.account_id=auth.uid()));
create policy profiles_member on public.medical_profiles for all using (exists(select 1 from public.family_accounts fa where fa.family_id=medical_profiles.family_id and fa.account_id=auth.uid())) with check (exists(select 1 from public.family_accounts fa where fa.family_id=medical_profiles.family_id and fa.account_id=auth.uid()));
create policy profile_items_member on public.medical_profile_items for all using (exists(select 1 from public.family_accounts fa where fa.family_id=medical_profile_items.family_id and fa.account_id=auth.uid())) with check (exists(select 1 from public.family_accounts fa where fa.family_id=medical_profile_items.family_id and fa.account_id=auth.uid()));
create function public.setup_family(p_name text) returns public.families language plpgsql security definer set search_path='' as $$ declare v_family public.families; begin if auth.uid() is null then raise exception 'unauthenticated' using errcode='28000'; end if exists(select 1 from public.family_accounts where account_id=auth.uid()) then raise exception 'family already configured' using errcode='23505'; end if char_length(btrim(p_name)) not between 1 and 120 then raise exception 'invalid name' using errcode='22023'; end if; insert into public.families(name) values(btrim(p_name)) returning * into v_family; insert into public.family_accounts(family_id,account_id) values(v_family.id,auth.uid()); return v_family; end $$;
revoke all on function public.setup_family(text) from public; grant execute on function public.setup_family(text) to authenticated;
create function public.put_medical_profile(p_family_id uuid,p_person_id uuid,p_profile jsonb) returns public.medical_profiles language plpgsql security invoker set search_path='' as $$ declare v_profile public.medical_profiles; begin if not exists(select 1 from public.people p where p.id=p_person_id and p.family_id=p_family_id) then raise exception 'not found' using errcode='P0002'; end if; insert into public.medical_profiles(family_id,person_id,blood_group,rhesus_factor,general_comment) values(p_family_id,p_person_id,p_profile->>'bloodGroup',p_profile->>'rhesusFactor',p_profile->>'generalComment') on conflict(person_id,family_id) do update set blood_group=excluded.blood_group,rhesus_factor=excluded.rhesus_factor,general_comment=excluded.general_comment,updated_at=now() returning * into v_profile; delete from public.medical_profile_items where medical_profile_id=v_profile.id and family_id=p_family_id; insert into public.medical_profile_items(family_id,medical_profile_id,category,name,description,status) select p_family_id,v_profile.id,x->>'category',x->>'name',x->>'description',x->>'status' from jsonb_array_elements(coalesce(p_profile->'items','[]'::jsonb)) x; return v_profile; end $$;
revoke execute on function public.put_medical_profile(uuid,uuid,jsonb) from public;
grant execute on function public.put_medical_profile(uuid,uuid,jsonb) to authenticated;
